package net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SelfRegistrationEnabledVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property self registration enabled of tenant config ")
  void test_self_registration_enabled_v_o_builder() {
    Assertions.assertFalse(SelfRegistrationEnabledVO.nullValue().isSelfRegistrationEnabled(),
        "A empty vo should have a null value");
    Assertions.assertFalse(SelfRegistrationEnabledVO.tryFrom(null).isSelfRegistrationEnabled(),
        "With a null value, no present result");
    Assertions.assertEquals(true, SelfRegistrationEnabledVO.from(true).isSelfRegistrationEnabled());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> SelfRegistrationEnabledVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", SelfRegistrationEnabledVO.from(true).toString());
  }
}
